249.         proof! { admit(); }
250.         let start_frame_number: usize = region.start().into_frame_number().into_raw_value();
251.         // VERUS REWRITE: replaced `start + size/FRAME_SIZE - 1` and `..=` (inclusive range)
252.         // with exclusive upper bound. RangeInclusive<usize> lacks ForLoopGhostIteratorNew.
253.         let num_frames: usize = region.size() / mem::FRAME_SIZE;
254.         let end_frame_number: usize = start_frame_number + num_frames;
255. 
256.         // When nightly-performance-optimizations is off, verify that every frame index in the
257.         // range is covered by the sparse bitmap. SparseBitmap::test() returns Ok(false) for
258.         // uncovered indices, which would incorrectly appear as "free" and pass the check below,
259.         // only to fail on set(). With the feature enabled this check is elided because
260.         // PhysicalAddress construction already guarantees valid physical addresses.
261.         #[cfg(not(feature = "nightly-performance-optimizations"))]
262.         #[verus_spec(invariant(true))]
263.         for index in start_frame_number..end_frame_number {
264.             proof! { admit(); }
265.             if self.bitmap.find_chunk(index).is_none() {
266.                 let uncovered_addr: usize = index * mem::FRAME_SIZE;
267.                 let reason: &str = "frame index not covered by any bitmap chunk";
268.                 #[cfg(not(verus_keep_ghost))]
269.                 error!("{} (frame={:#010x}, region={:?})", reason, uncovered_addr, region);
270.                 return Err(Error::new(ErrorCode::InvalidArgument, reason));
271.             }
272.         }
273. 
274.         // Check if all frames in the range are free.
275.         #[verus_spec(invariant(true))]
276.         for index in start_frame_number..end_frame_number {
277.             proof! { admit(); }
278.             match self.bitmap.test(index) {
279.                 Ok(false) => {
280.                     // Frame is free — nothing to do.
281.                 },
282.                 Ok(true) => {
283.                     let conflicting_addr: usize = index * mem::FRAME_SIZE;
284.                     let region_start: usize = region.start().into_raw_value();
285.                     let region_end: usize = region_start.saturating_add(region.size());
286.                     let reason: &str = "frame is already allocated";
